 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Image Preview</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f3f6fb;
         --surface: #ffffff;
         --surface-muted: #eef3f9;
         --text: #162033;
         --muted: #5f6c83;
         --border: #d8e0ec;
         --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
         --accent: #1d4ed8;
         --accent-strong: #1e40af;
         --danger: #c62828;
         --danger-strong: #8f1d1d;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top left, #ffffff 0, #f8fbff 32%, transparent 58%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
         color: var(--text);
       }

       a,
       button {
         transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-220%);
         background: var(--text);
         color: #fff;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       :focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       .page {
         width: min(100%, 72rem);
         margin: 0 auto;
         padding: 2rem 1.25rem 3rem;
       }

       .topbar {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         margin-bottom: 2rem;
       }

       .brand {
         font-size: 0.95rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
         color: var(--accent-strong);
       }

       .library-link {
         color: var(--text);
         text-decoration: none;
         font-weight: 600;
       }

       .library-link:hover {
         color: var(--accent-strong);
       }

       .hero {
         display: grid;
         grid-template-columns: minmax(0, 1.6fr) minmax(16rem, 1fr);
         gap: 1.5rem;
         align-items: start;
       }

       .preview-card,
       .details-card {
         background: var(--surface);
         border: 1px solid var(--border);
         border-radius: 1.5rem;
         box-shadow: var(--shadow);
       }

       .preview-card {
         padding: 1.25rem;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.4rem;
         padding: 0.45rem 0.75rem;
         border-radius: 999px;
         background: #e8f0ff;
         color: var(--accent-strong);
         font-size: 0.88rem;
         font-weight: 700;
       }

       h1 {
         margin: 1rem 0 0.5rem;
         font-size: clamp(2rem, 4vw, 3.3rem);
         line-height: 1.05;
       }

       .intro {
         margin: 0 0 1.5rem;
         max-width: 40rem;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.6;
       }

       figure {
         margin: 0;
       }

       .image-shell {
         position: relative;
         overflow: hidden;
         border-radius: 1.25rem;
         border: 1px solid var(--border);
         background: linear-gradient(135deg, #dce8ff 0%, #f7fbff 42%, #d5e6ff 100%);
       }

       .image-shell img {
         display: block;
         width: 100%;
         height: auto;
         aspect-ratio: 16 / 10;
         object-fit: cover;
       }

       figcaption {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         padding-top: 1rem;
       }

       .meta h2 {
         margin: 0;
         font-size: 1.2rem;
       }

       .meta p {
         margin: 0.35rem 0 0;
         color: var(--muted);
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem;
       }

       button {
         appearance: none;
         border: 1px solid transparent;
         border-radius: 999px;
         padding: 0.9rem 1.2rem;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
       }

       .secondary-action {
         background: var(--surface-muted);
         border-color: var(--border);
         color: var(--text);
       }

       .secondary-action:hover {
         background: #e6edf7;
       }

       .trigger,
       .confirm-button {
         background: var(--danger);
         color: #fff;
       }

       .trigger:hover,
       .confirm-button:hover {
         background: var(--danger-strong);
       }

       .details-card {
         padding: 1.5rem;
       }

       .details-card h2 {
         margin-top: 0;
         margin-bottom: 1rem;
         font-size: 1.1rem;
       }

       .stats {
         display: grid;
         gap: 0.9rem;
         margin: 0;
       }

       .stats div {
         padding: 1rem;
         border-radius: 1rem;
         background: var(--surface-muted);
       }

       .stats dt {
         margin: 0 0 0.35rem;
         color: var(--muted);
         font-size: 0.92rem;
       }

       .stats dd {
         margin: 0;
         font-weight: 700;
         font-size: 1rem;
       }

       .status {
         min-height: 1.5rem;
         margin-top: 1rem;
         color: var(--accent-strong);
         font-weight: 600;
       }

       dialog {
         width: min(100% - 2rem, 29rem);
         border: none;
         border-radius: 1.5rem;
         padding: 0;
         box-shadow: 0 28px 80px rgba(15, 23, 42, 0.4);
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.58);
         backdrop-filter: blur(6px);
       }

       .dialog-content {
         padding: 1.5rem;
       }

       .dialog-icon {
         display: inline-flex;
         align-items: center;
         justify-content: center;
         width: 3rem;
         height: 3rem;
         border-radius: 999px;
         background: #ffe3e3;
         color: var(--danger-strong);
         font-size: 1.3rem;
         font-weight: 800;
       }

       .dialog-content h2 {
         margin: 1rem 0 0.5rem;
         font-size: 1.4rem;
       }

       .dialog-content p {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .dialog-actions {
         display: flex;
         flex-wrap: wrap;
         justify-content: flex-end;
         gap: 0.75rem;
         margin-top: 1.5rem;
       }

       @media (max-width: 52rem) {
         .hero {
           grid-template-columns: 1fr;
         }
       }

       @media (max-width: 36rem) {
         .page {
           padding-inline: 1rem;
         }

         .topbar,
         figcaption,
         .dialog-actions {
           align-items: stretch;
         }

         .topbar,
         figcaption,
         .actions,
         .dialog-actions {
           flex-direction: column;
         }

         .actions > *,
         .dialog-actions > * {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
           color: CanvasText;
         }

         .preview-card,
         .details-card,
         .image-shell,
         .stats div,
         dialog,
         .secondary-action,
         .trigger,
         .confirm-button {
           border: 1px solid ButtonText;
         }

         .preview-card,
         .details-card,
         .stats div,
         dialog {
           background: Canvas;
           color: CanvasText;
           box-shadow: none;
         }

         .eyebrow,
         .secondary-action,
         .trigger,
         .confirm-button,
         .dialog-icon {
           background: ButtonFace;
           color: ButtonText;
         }

         .library-link,
         .status,
         .brand,
         .intro,
         .meta p,
         .dialog-content p,
         .stats dt {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main class="page" id="main-content">
       <header class="topbar">
         <div class="brand">Pixel Library</div>
         <a class="library-link" href="/" aria-label="Back to library">Back to library</a>
       </header>

       <section class="hero" aria-labelledby="page-title">
         <article class="preview-card">
           <span class="eyebrow">Image preview</span>
           <h1 id="page-title">Review before removing</h1>
           <p class="intro">
             Preview the selected image, check its details, and confirm whether it should be deleted from your library.
           </p>

           <figure>
             <div class="image-shell">
               <img
                 src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 1000'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%23e7f0ff'/%3E%3Cstop offset='100%25' stop-color='%23bfd7ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1600' height='1000' fill='url(%23sky)'/%3E%3Ccircle cx='1210' cy='196' r='104' fill='%23fff7bf'/%3E%3Cpath d='M0 685c154-92 270-116 406-76s196 126 355 119 206-101 374-104 279 72 465 183v193H0Z' fill='%2388b4ff'/%3E%3Cpath d='M0 763c132-41 242-34 360 16s178 118 308 102 183-98 319-104 275 42 613 168v55H0Z' fill='%23507fd9'/%3E%3Cpath d='M239 648 531 372l179 198 97-98 236 248H239Z' fill='%23213f7d' opacity='.9'/%3E%3Cpath d='m766 648 139-148 112 117 73-83 271 114H766Z' fill='%23315297' opacity='.88'/%3E%3C/svg%3E"
                 alt="Coastal mountains under a bright sky"
               />
             </div>
             <figcaption>
               <div class="meta">
                 <h2>Summer Horizon</h2>
                 <p>Uploaded May 2, 2026 . 4096 x 2560 px</p>
               </div>
               <div class="actions">
                 <button type="button" class="secondary-action">Download</button>
                 <button type="button" class="trigger">Delete image</button>
               </div>
             </figcaption>
           </figure>
         </article>

         <aside class="details-card" aria-labelledby="details-title">
           <h2 id="details-title">Image details</h2>
           <dl class="stats">
             <div>
               <dt>Collection</dt>
               <dd>Travel campaigns</dd>
             </div>
             <div>
               <dt>Photographer</dt>
               <dd>Avery Nguyen</dd>
             </div>
             <div>
               <dt>Usage rights</dt>
               <dd>Internal library</dd>
             </div>
           </dl>
           <p class="status" id="status-message" aria-live="polite"></p>
         </aside>
       </section>
     </main>

     <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
       <form class="dialog-content" method="dialog">
         <div class="dialog-icon" aria-hidden="true">!</div>
         <h2 id="dialog-title">Delete this image?</h2>
         <p id="dialog-description">
           Are you sure you want to delete <strong>Summer Horizon</strong> from your library? This action cannot be undone.
         </p>
         <div class="dialog-actions">
           <button type="submit" class="secondary-action" value="cancel">Cancel</button>
           <button type="button" class="confirm-button" id="confirm-delete">Delete image</button>
         </div>
       </form>
     </dialog>

     <script>
       const trigger = document.querySelector(".trigger");
       const dialog = document.getElementById("delete-dialog");
       const confirmDelete = document.getElementById("confirm-delete");
       const statusMessage = document.getElementById("status-message");

       trigger.addEventListener("click", () => {
         dialog.showModal();
       });

       dialog.addEventListener("click", (event) => {
         const bounds = dialog.getBoundingClientRect();
         const clickedOutside =
           event.clientX < bounds.left ||
           event.clientX > bounds.right ||
           event.clientY < bounds.top ||
           event.clientY > bounds.bottom;

         if (clickedOutside) {
           dialog.close("cancel");
         }
       });

       confirmDelete.addEventListener("click", () => {
         dialog.close("deleted");
         trigger.disabled = true;
         trigger.setAttribute("aria-disabled", "true");
         trigger.textContent = "Image deleted";
         statusMessage.textContent = "Summer Horizon was deleted from your library.";
       });
     </script>
   </body>
 </html>

